"""ADR-0383 D6 — the MCP service may never be wired to AUTHORISE anything.

The customer MCP channel is propose-only: a third-party model may create a proposal, and the
customer authorises it in the bank app under full SCA. The structural form of that rule is that no
REST client interface in `openbank-mcp-service/src/main` declares a non-GET method against a
payment, limit, beneficiary, SCA/challenge, card, mandate or delegation-management target. A client
that can POST to one of those is a client that can move money or change security state, whatever
the tool layer above it promises.

What is checked, per interface in `openbank-mcp-service/src/main/**/*.kt`:
  * every JAX-RS verb annotation other than GET/HEAD/OPTIONS on a method (fully qualified forms and
    `@HttpMethod("X")` included), comments stripped first so a KDoc mentioning `@POST` is not a
    finding;
  * the TARGET is `configKey` of `@RegisterRestClient` plus the class `@Path` plus the method
    `@Path`, so a client of `sca-service` posting to `/api/v1/challenges` is caught by its config
    key even though the path alone would not say "sca";
  * SUPERTYPES are followed. A client interface may inherit its methods (`AccountServiceClient :
    AccountsApi`). A supertype declared in repo source is parsed the same way; one generated by an
    `openbank-client-*` module is resolved from that module's provider `openapi.yaml`, restricted to
    the tags the module generates. A supertype that resolves to neither is a FINDING, not a pass:
    a method this gate cannot see is exactly a method it cannot vouch for.

The allow-list is empty today. The future proposal-store client (ADR-0383 D6) is the first expected
entry, and it is added here explicitly, with a reason, so that reviewing it is unavoidable.

Usage:
  check-mcp-customer-channel-propose-only.py            # scan the repo, exit 1 on findings
  check-mcp-customer-channel-propose-only.py --self-test
"""
from __future__ import annotations

import argparse
import pathlib
import re
import sys
import tempfile

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
import gatelib  # noqa: E402

REPO = pathlib.Path(__file__).resolve().parents[2]
MCP_SRC = pathlib.Path("openbank-mcp-service/src/main")

# (interface simple name, HTTP method, full target) -> reason. Empty by decision (ADR-0383 D6).
ALLOWLIST: dict[tuple[str, str, str], str] = {}

# Measured when this gate was written: `AccountServiceClient : AccountsApi` inherits EVERY operation
# of account-service's `Accounts` tag, because the shared `openbank-client-account` facade takes the
# whole generated interface. Three of those are writes against the savings-goal delegation proposal
# routes. No MCP code calls them (nothing in openbank-mcp-service/src/main names them), but they are
# declared on a client that authenticates as an M2M principal, which is exactly what this gate
# exists to refuse. The fix is upstream — generate a read-only surface for this consumer — not here.
# This is a BASELINE, not an allow-list: it may only shrink. An entry that no longer matches a real
# finding fails the gate, so the day the client stops inheriting them, the entry must be deleted.
INHERITED_BASELINE: dict[tuple[str, str, str], str] = {
    ("AccountServiceClient", "POST", "/api/v1/accounts/{accountId}/savings-goal/delegation/proposals"):
        "inherited from generated AccountsApi, never called by MCP; narrow openbank-client-account",
    ("AccountServiceClient", "POST", "/api/v1/accounts/{accountId}/savings-goal/delegation/proposals/{proposalId}/decide"):
        "inherited from generated AccountsApi, never called by MCP; narrow openbank-client-account",
    ("AccountServiceClient", "DELETE", "/api/v1/accounts/{accountId}/savings-goal/delegation/proposals/{proposalId}"):
        "inherited from generated AccountsApi, never called by MCP; narrow openbank-client-account",
}

SAFE_METHODS = {"GET", "HEAD", "OPTIONS"}
VERB_RE = re.compile(
    r"@(?:jakarta\.ws\.rs\.|javax\.ws\.rs\.)?(GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS)\b"
    r"|@(?:jakarta\.ws\.rs\.|javax\.ws\.rs\.)?HttpMethod\(\s*\"([A-Za-z]+)\"\s*\)"
)
PATH_RE = re.compile(r"@(?:jakarta\.ws\.rs\.|javax\.ws\.rs\.)?Path\(\s*(?:value\s*=\s*)?\"([^\"]*)\"\s*\)")
CONFIG_KEY_RE = re.compile(r"@RegisterRestClient\s*\(([^)]*)\)")
REGISTER_RE = re.compile(r"@RegisterRestClient\b")
# A target token must start at a word edge, so `discard` is not `card` and `escalate` is not `sca`.
FORBIDDEN_RE = re.compile(
    r"(?<![a-z])(payment|limit|beneficiar|sca(?![a-z])|challenge|card|mandate|delegation)",
    re.IGNORECASE,
)
INTERFACE_RE = re.compile(r"\binterface\s+([A-Za-z_][A-Za-z0-9_]*)\s*(?::\s*([^{\n]+?))?\s*(\{|\n|$)")
IMPORT_RE = re.compile(r"^\s*import\s+([A-Za-z0-9_.]+)(?:\s+as\s+([A-Za-z0-9_]+))?\s*$", re.MULTILINE)
GEN_API_PACKAGE_RE = re.compile(r"apiPackage\.set\(\s*\"([^\"]+)\"\s*\)")
GEN_APIS_RE = re.compile(r"\"apis\"\s+to\s+\"([^\"]+)\"")
GEN_SPEC_RE = re.compile(r"\.file\(\s*\"([^\"]+openapi\.ya?ml)\"\s*\)")
HTTP_VERBS = ("get", "put", "post", "delete", "options", "head", "patch", "trace")


def strip_comments(text: str) -> str:
    """Remove // and /* */ comments while leaving string literals (and their `//`) intact."""
    out: list[str] = []
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if text.startswith('"""', i):
            j = text.find('"""', i + 3)
            j = n if j < 0 else j + 3
            out.append(text[i:j])
            i = j
        elif c == '"':
            j = i + 1
            while j < n and text[j] != '"' and text[j] != "\n":
                j += 2 if text[j] == "\\" else 1
            out.append(text[i : j + 1])
            i = j + 1
        elif text.startswith("//", i):
            j = text.find("\n", i)
            i = n if j < 0 else j
        elif text.startswith("/*", i):
            j = text.find("*/", i + 2)
            seg = text[i : (n if j < 0 else j + 2)]
            out.append("\n" * seg.count("\n"))
            i = n if j < 0 else j + 2
        else:
            out.append(c)
            i += 1
    return "".join(out)


def _body(text: str, open_idx: int) -> str:
    depth, i = 0, open_idx
    while i < len(text):
        if text[i] == "{":
            depth += 1
        elif text[i] == "}":
            depth -= 1
            if depth == 0:
                return text[open_idx + 1 : i]
        i += 1
    return text[open_idx + 1 :]


def join_path(*parts: str) -> str:
    segs = [p.strip("/") for p in parts if p and p.strip("/")]
    return "/" + "/".join(segs)


class Iface:
    def __init__(self, name: str, file: pathlib.Path, header: str, body: str, supers: list[str], imports: dict[str, str]):
        self.name, self.file, self.supers, self.imports = name, file, supers, imports
        self.is_client = bool(REGISTER_RE.search(header))
        ck = CONFIG_KEY_RE.search(header)
        key = ""
        if ck:
            m = re.search(r"configKey\s*=\s*\"([^\"]*)\"", ck.group(1))
            key = m.group(1) if m else ""
        self.config_key = key
        cp = PATH_RE.search(header)
        self.class_path = cp.group(1) if cp else ""
        self.methods: list[tuple[str, str, str]] = []  # (verb, method path, fun name)
        chunks = re.split(r"(\bfun\s+[A-Za-z_][A-Za-z0-9_]*)", body)
        prefix = chunks[0]
        for k in range(1, len(chunks), 2):
            fun_name = chunks[k].split()[1]
            # `prefix` holds only the text after the previous fun's signature, i.e. this fun's own
            # annotation block.
            ann = prefix
            verbs = [(m.group(1) or m.group(2) or "").upper() for m in VERB_RE.finditer(ann)]
            mp = PATH_RE.findall(ann)
            for verb in verbs:
                self.methods.append((verb, mp[-1] if mp else "", fun_name))
            # Next fun's annotation block starts after this fun's signature line(s).
            rest = chunks[k + 1] if k + 1 < len(chunks) else ""
            sig_end = _signature_end(rest)
            prefix = rest[sig_end:]


def _signature_end(rest: str) -> int:
    """Index just past this fun's parameter list (and return type / expression body line)."""
    depth, i = 0, 0
    started = False
    while i < len(rest):
        ch = rest[i]
        if ch == "(":
            depth += 1
            started = True
        elif ch == ")":
            depth -= 1
            if started and depth == 0:
                nl = rest.find("\n", i)
                return len(rest) if nl < 0 else nl
        i += 1
    return len(rest)


def parse_interfaces(file: pathlib.Path, text: str) -> list[Iface]:
    clean = strip_comments(text)
    imports = {(m.group(2) or m.group(1).rsplit(".", 1)[-1]): m.group(1) for m in IMPORT_RE.finditer(clean)}
    pkg = re.search(r"^\s*package\s+([A-Za-z0-9_.]+)", clean, re.MULTILINE)
    found: list[Iface] = []
    prev_end = 0
    for m in INTERFACE_RE.finditer(clean):
        start = m.start()
        header = clean[prev_end:start]
        supers = [s.strip().split("<")[0].split("(")[0].strip() for s in (m.group(2) or "").split(",") if s.strip()]
        body = ""
        if m.group(3) == "{":
            body = _body(clean, m.end() - 1)
            prev_end = m.end() - 1 + len(body) + 2
        else:
            prev_end = m.end()
        local = {n: f"{pkg.group(1)}.{n}" if pkg else n for n in supers if n not in imports}
        found.append(Iface(m.group(1), file, header, body, supers, {**local, **imports}))
    return found


class Resolver:
    def __init__(self, root: pathlib.Path):
        self.root = root
        self._src: dict[str, list[Iface]] | None = None

    def source_index(self) -> dict[str, list[Iface]]:
        if self._src is None:
            self._src = {}
            for f in sorted(self.root.glob("openbank-*/src/main/**/*.kt")):
                try:
                    txt = f.read_text(encoding="utf-8")
                except (OSError, UnicodeDecodeError):
                    continue
                if "interface" not in txt:
                    continue
                for i in parse_interfaces(f, txt):
                    self._src.setdefault(i.name, []).append(i)
        return self._src

    def generated(self, fqcn: str) -> list[tuple[str, str]] | None:
        """(VERB, path) for an `openbank-client-*` generated API, or None when not one."""
        pkg, _, simple = fqcn.rpartition(".")
        for build in sorted(self.root.glob("openbank-client-*/build.gradle.kts")):
            txt = build.read_text(encoding="utf-8")
            ap = GEN_API_PACKAGE_RE.search(txt)
            if not ap or ap.group(1) != pkg:
                continue
            spec_m, apis_m = GEN_SPEC_RE.search(txt), GEN_APIS_RE.search(txt)
            if not spec_m or not apis_m:
                return None
            tags = {t.strip() for t in apis_m.group(1).split(":") if t.strip()}
            if not simple.endswith("Api") or simple[: -len("Api")] not in tags:
                return None
            spec = gatelib.load_yaml(self.root / spec_m.group(1)) or {}
            ops: list[tuple[str, str]] = []
            for path, item in (spec.get("paths") or {}).items():
                for verb in HTTP_VERBS:
                    op = (item or {}).get(verb)
                    if isinstance(op, dict) and tags & set(op.get("tags") or []):
                        ops.append((verb.upper(), str(path)))
            return ops
        return None


def check(root: pathlib.Path, baseline: dict | None = None) -> tuple[list[str], int]:
    baseline = INHERITED_BASELINE if baseline is None else baseline
    used: set[tuple[str, str, str]] = set()
    resolver = Resolver(root)
    findings: list[str] = []
    clients = 0
    for f in sorted((root / MCP_SRC).glob("**/*.kt")):
        rel = f.relative_to(root)
        for iface in parse_interfaces(f, f.read_text(encoding="utf-8")):
            if iface.is_client:
                clients += 1
            ops: list[tuple[str, str, str]] = [(v, join_path(iface.class_path, p), n) for v, p, n in iface.methods]
            seen: set[str] = set()
            stack = list(iface.supers)
            while stack:
                sup = stack.pop()
                if sup in seen:
                    continue
                seen.add(sup)
                fq = iface.imports.get(sup, sup)
                candidates = resolver.source_index().get(sup, [])
                if candidates:
                    for c in candidates:
                        ops += [(v, join_path(iface.class_path, c.class_path, p), f"{sup}.{n}") for v, p, n in c.methods]
                        stack += c.supers
                    continue
                gen = resolver.generated(fq)
                if gen is not None:
                    ops += [(v, join_path(iface.class_path, p), f"{sup} (generated)") for v, p in gen]
                    continue
                if iface.is_client or iface.methods:
                    findings.append(
                        f"{rel}: {iface.name} inherits {fq}, which resolves to no repo source and no "
                        "openbank-client-* generated API — its methods cannot be checked, so they are refused"
                    )
            for verb, path, fun in ops:
                if verb in SAFE_METHODS:
                    continue
                target = f"{iface.config_key} {path}".strip()
                hit = FORBIDDEN_RE.search(target)
                if not hit:
                    continue
                key = (iface.name, verb, path)
                if key in ALLOWLIST:
                    continue
                if key in baseline and "(generated)" in fun:
                    used.add(key)
                    continue
                findings.append(
                    f"{rel}: {iface.name}.{fun} declares {verb} {path} (configKey '{iface.config_key}') — "
                    f"a non-GET call against a '{hit.group(1).lower()}' target; the customer MCP channel is "
                    "propose-only (ADR-0383 D6)"
                )
    for key in sorted(set(baseline) - used):
        findings.append(f"stale INHERITED_BASELINE entry {key}: it matches no finding any more — delete it")
    return findings, clients


FIXTURES = {
    "positive_post_payment": (
        """package x
@RegisterRestClient(configKey = "domestic-payment-service")
@Path("/api/v1/domestic-payments")
interface Bad {
    @POST
    fun initiate(body: String): String
}
""",
        True,
    ),
    "positive_sca_by_config_key": (
        """package x
@RegisterRestClient(configKey = "sca-service")
@Path("/api/v1/challenges")
interface Bad {
    @jakarta.ws.rs.PUT
    @Path("/{id}/confirm")
    suspend fun confirm(@PathParam("id") id: String): String
}
""",
        True,
    ),
    "positive_inherited_from_source": (
        """package x
interface CardOps {
    @DELETE
    @Path("/api/v1/cards/{id}")
    fun block(@PathParam("id") id: String): String
}
@RegisterRestClient(configKey = "card-service")
interface Client : CardOps
""",
        True,
    ),
    "positive_unresolvable_supertype": (
        """package x
import com.elsewhere.UnknownApi
@RegisterRestClient(configKey = "account-service")
interface Client : UnknownApi
""",
        True,
    ),
    "negative_reads_and_consent_validate": (
        """package x
/**
 * Prose mentioning @POST /api/v1/payments must not be a finding.
 */
@RegisterRestClient(configKey = "domestic-payment-service")
@Path("/api/v1/domestic-payments")
interface Reads {
    // @POST commented out
    @GET
    @Path("/{paymentId}")
    fun get(@PathParam("paymentId") id: String): String
}
@RegisterRestClient(configKey = "consent-service")
@Path("/api/v1/consents")
interface Consent {
    @POST
    @Path("/{id}/validate")
    fun validate(@PathParam("id") id: String, body: String): String
}
""",
        False,
    ),
}


def self_test() -> int:
    failures = 0
    for name, (src, must_flag) in FIXTURES.items():
        with tempfile.TemporaryDirectory() as tmp:
            root = pathlib.Path(tmp)
            d = root / MCP_SRC / "kotlin" / "x"
            d.mkdir(parents=True)
            (d / "Fixture.kt").write_text(src, encoding="utf-8")
            findings, _ = check(root, baseline={})
        ok = bool(findings) == must_flag
        failures += 0 if ok else 1
        print(f"{'ok  ' if ok else 'FAIL'} {name}: expected {'findings' if must_flag else 'clean'}, got {len(findings)}")
        for f in findings:
            print(f"       {f}")
    # A baseline entry matching nothing must FAIL, so the baseline can only shrink.
    with tempfile.TemporaryDirectory() as tmp:
        root = pathlib.Path(tmp)
        (root / MCP_SRC).mkdir(parents=True)
        stale, _ = check(root, baseline={("Gone", "POST", "/api/v1/payments"): "x"})
    ok = any("stale INHERITED_BASELINE" in f for f in stale)
    failures += 0 if ok else 1
    print(f"{'ok  ' if ok else 'FAIL'} stale baseline entry is a finding")
    # The generated-API path: a supertype produced by an openbank-client-* module is resolved from
    # the provider spec, restricted to the generated tag — a write in that tag is a finding, a write
    # in another tag is not this client's.
    for tag_of_write, must_flag in (("Cards", True), ("Other", False)):
        with tempfile.TemporaryDirectory() as tmp:
            root = pathlib.Path(tmp)
            gen = root / "openbank-client-fake"
            gen.mkdir()
            (gen / "build.gradle.kts").write_text(
                'val s = rootProject.layout.projectDirectory\n    .file("fake/openapi.yaml").asFile\n'
                'apiPackage.set("com.openbank.clients.fake.api")\n"apis" to "Cards",\n',
                encoding="utf-8",
            )
            (root / "fake").mkdir()
            (root / "fake" / "openapi.yaml").write_text(
                "paths:\n  /api/v1/cards/{id}:\n    get:\n      tags: [Cards]\n"
                f"    post:\n      tags: [{tag_of_write}]\n",
                encoding="utf-8",
            )
            d = root / MCP_SRC / "kotlin" / "x"
            d.mkdir(parents=True)
            (d / "Fixture.kt").write_text(
                "package x\nimport com.openbank.clients.fake.api.CardsApi\n"
                '@RegisterRestClient(configKey = "card-service")\ninterface C : CardsApi\n',
                encoding="utf-8",
            )
            findings, _ = check(root, baseline={})
        ok = bool(findings) == must_flag
        failures += 0 if ok else 1
        print(f"{'ok  ' if ok else 'FAIL'} generated supertype, write tagged {tag_of_write}: {len(findings)} finding(s)")
        for f in findings:
            print(f"       {f}")
    # The real tree is deliberately NOT read here: the gate's own run covers it, and the self-test
    # must touch only its fixtures so its declared inputs are exactly this script.
    print("self-test PASSED" if failures == 0 else f"self-test FAILED ({failures})")
    return 0 if failures == 0 else 1


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--self-test", action="store_true")
    args = ap.parse_args()
    if args.self_test:
        return self_test()
    findings, clients = check(REPO)
    gatelib.subjects(clients, "REST client interfaces in openbank-mcp-service/src/main")
    for f in findings:
        print(f"FINDING {f}")
    if findings:
        print(f"mcp-customer-channel-propose-only: {len(findings)} finding(s)")
        return 1
    print(f"mcp-customer-channel-propose-only: OK — {clients} REST client(s), no non-GET call to a protected target")
    return 0


if __name__ == "__main__":
    sys.exit(main())
